export const getUploadResearchImageUrl = () => {




  return `/api/admin/uploads`
}

/**
 * @summary Validate and upload an image to Cloudinary
 */
export const uploadResearchImage = async (imageUploadInput: ImageUploadInput, options?: Parameters<typeof customFetch>[1]): Promise<ImageUploadResult> => {
    const formData = new FormData();
formData.append(`image`, imageUploadInput.image);

  return customFetch<ImageUploadResult>(getUploadResearchImageUrl(),
  {
    ...options,
    method: 'POST'
    ,
    body: formData
  }
);}





